"""Cron-style schedules. SCHEDULE.md has the full rules."""

import calendar
import re
from datetime import datetime, timedelta

_SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}

_RANGES = {
    "minute": (0, 59),
    "hour": (0, 23),
    "day": (1, 31),
    "month": (1, 12),
    "weekday": (0, 7),
}

_MONTHS = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

_WEEKDAYS = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3,
    "THU": 4, "FRI": 5, "SAT": 6,
}

_NUMBER = re.compile(r"[0-9]+\Z")


class _Schedule:
    __slots__ = (
        "minutes", "hours", "days", "months", "weekdays",
        "last_day", "last_weekdays", "nth_weekdays",
    )


def _value(token, kind):
    low, high = _RANGES[kind]
    if _NUMBER.fullmatch(token):
        number = int(token)
        if not low <= number <= high:
            raise ValueError(f"value out of range: {token!r}")
        return number
    name = token.upper()
    table = _MONTHS if kind == "month" else _WEEKDAYS if kind == "weekday" else None
    if table is not None and name in table:
        return table[name]
    raise ValueError(f"bad value in {kind}: {token!r}")


def _item_values(item, kind):
    low, high = _RANGES[kind]
    if "/" in item:
        if item.count("/") != 1:
            raise ValueError(f"bad step: {item!r}")
        base, step_text = item.split("/")
        if not _NUMBER.fullmatch(step_text):
            raise ValueError(f"bad step: {item!r}")
        step = int(step_text)
        if step < 1:
            raise ValueError(f"bad step: {item!r}")
        if base == "*":
            values = list(range(low, high + 1))
        elif _NUMBER.fullmatch(base):
            start = int(base)
            if not low <= start <= high:
                raise ValueError(f"value out of range: {base!r}")
            values = list(range(start, high + 1))
        elif "-" in base:
            ends = base.split("-")
            if len(ends) != 2 or not all(_NUMBER.fullmatch(e) for e in ends):
                raise ValueError(f"bad step: {item!r}")
            first, last = int(ends[0]), int(ends[1])
            if not (low <= first <= high and low <= last <= high):
                raise ValueError(f"value out of range: {base!r}")
            if first > last:
                raise ValueError(f"bad range: {base!r}")
            values = list(range(first, last + 1))
        else:
            raise ValueError(f"bad step: {item!r}")
        return values[::step]
    if item == "*":
        return list(range(low, high + 1))
    if "-" in item:
        ends = item.split("-")
        if len(ends) != 2:
            raise ValueError(f"bad range: {item!r}")
        first = _value(ends[0], kind)
        last = _value(ends[1], kind)
        if first > last:
            raise ValueError(f"bad range: {item!r}")
        return list(range(first, last + 1))
    return [_value(item, kind)]


def _parse_field(text, kind):
    low, high = _RANGES[kind]
    if text == "?":
        if kind not in ("day", "weekday"):
            raise ValueError("'?' outside the day fields")
        return set(range(low, high + 1)), []
    if "?" in text:
        raise ValueError("bad '?'")
    items = text.split(",")
    if any(item == "" for item in items):
        raise ValueError(f"empty item in {text!r}")
    values = set()
    specials = []
    for item in items:
        if kind == "day" and item == "L":
            specials.append(("last", None))
            continue
        if kind == "weekday":
            match = re.fullmatch(r"([0-9]+)L", item)
            if match:
                number = int(match.group(1))
                if not 0 <= number <= 7:
                    raise ValueError(f"value out of range: {item!r}")
                specials.append(("last_weekday", number))
                continue
            match = re.fullmatch(r"([0-9]+)#([0-9]+)", item)
            if match:
                number = int(match.group(1))
                rank = int(match.group(2))
                if not 0 <= number <= 7:
                    raise ValueError(f"value out of range: {item!r}")
                if not 1 <= rank <= 5:
                    raise ValueError(f"value out of range: {item!r}")
                specials.append(("nth_weekday", (number, rank)))
                continue
        values.update(_item_values(item, kind))
    return values, specials


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError(f"bad expression: {expr!r}")
    text = expr.strip()
    if text.startswith("@"):
        if text.lower() not in _SHORTCUTS:
            raise ValueError(f"unknown shortcut: {expr!r}")
        text = _SHORTCUTS[text.lower()]
    fields = re.split(r"[ \t]+", text)
    if len(fields) != 5:
        raise ValueError(f"wrong number of fields: {expr!r}")

    schedule = _Schedule()
    schedule.minutes = _parse_field(fields[0], "minute")[0]
    schedule.hours = _parse_field(fields[1], "hour")[0]
    days, day_specials = _parse_field(fields[2], "day")
    schedule.days = days
    schedule.last_day = bool(day_specials)
    schedule.months = _parse_field(fields[3], "month")[0]
    weekdays, weekday_specials = _parse_field(fields[4], "weekday")
    schedule.weekdays = {0 if value == 7 else value for value in weekdays}
    schedule.last_weekdays = [
        (0 if value == 7 else value)
        for tag, value in weekday_specials if tag == "last_weekday"
    ]
    schedule.nth_weekdays = [
        (0 if value[0] == 7 else value[0], value[1])
        for tag, value in weekday_specials if tag == "nth_weekday"
    ]
    return schedule


def _month_length(when):
    return calendar.monthrange(when.year, when.month)[1]


def _dom_matches(schedule, when):
    if when.day in schedule.days:
        return True
    return schedule.last_day and when.day == _month_length(when)


def _first_weekday_of_month(when, weekday):
    first = datetime(when.year, when.month, 1).weekday()
    first = (first + 1) % 7
    return 1 + (weekday - first) % 7


def _dow_matches(schedule, when):
    weekday = (when.weekday() + 1) % 7
    if weekday in schedule.weekdays:
        return True
    if weekday in schedule.last_weekdays and when.day + 7 > _month_length(when):
        return True
    for number, rank in schedule.nth_weekdays:
        if number == weekday:
            if when.day == _first_weekday_of_month(when, number) + 7 * (rank - 1):
                return True
    return False


def _day_allowed(schedule, when):
    return _dom_matches(schedule, when) and _dow_matches(schedule, when)


def _matches(schedule, when):
    return (
        when.minute in schedule.minutes
        and when.hour in schedule.hours
        and when.month in schedule.months
        and _day_allowed(schedule, when)
    )


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    schedule = _parse(expr)
    return _matches(schedule, when)


def _next_at_least(values, current):
    later = [value for value in values if value >= current]
    return min(later) if later else None


def _next_day_start(when):
    try:
        when = when + timedelta(days=1)
    except OverflowError:
        return None
    return when.replace(hour=0, minute=0, second=0, microsecond=0)


def _next_month_start(when):
    year, month = when.year, when.month + 1
    if month == 13:
        year, month = year + 1, 1
    if year > 9999:
        return None
    return datetime(year, month, 1)


def _next_hour_start(when):
    try:
        return when.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)
    except OverflowError:
        return None


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    schedule = _parse(expr)
    try:
        candidate = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None
    try:
        limit = after + timedelta(days=20 * 365)
    except OverflowError:
        limit = datetime.max

    while candidate <= limit:
        if candidate.month not in schedule.months:
            candidate = _next_month_start(candidate)
            if candidate is None:
                return None
            continue
        if not _day_allowed(schedule, candidate):
            candidate = _next_day_start(candidate)
            if candidate is None:
                return None
            continue
        if candidate.hour not in schedule.hours:
            hour = _next_at_least(schedule.hours, candidate.hour)
            if hour is None:
                candidate = _next_day_start(candidate)
                if candidate is None:
                    return None
            else:
                candidate = candidate.replace(hour=hour, minute=0)
            continue
        minute = _next_at_least(schedule.minutes, candidate.minute)
        if minute is None:
            candidate = _next_hour_start(candidate)
            if candidate is None:
                return None
            continue
        candidate = candidate.replace(minute=minute, second=0, microsecond=0)
        return candidate if candidate <= limit else None
    return None

